/**
 * Parses an already-JSON-parsed Docusaurus sidebars.json value into a
 * flat list of nav entries. Docusaurus's sidebar item shapes (see their
 * docs): a bare string is a doc ID; an object needs a `type` of `doc`,
 * `category`, `link`, or `autogenerated` (a few other experimental
 * types exist upstream and are reported as `unknown` rather than
 * guessed at). Pure data transformation -- no file I/O, no execution.
 *
 * Exports:
 * - parseDocusaurusSidebars(parsedJson): returns { entries, notes }.
 *   `entries` is a flat array of
 *   { kind: "doc" | "link" | "autogenerated" | "unknown", docId?,
 *     dirName?, label?, href?, depth, sidebarId }, in document order,
 *   `depth` counting category nesting (0 = top level of its sidebar).
 *   `notes` lists anything the parser couldn't resolve statically, such
 *   as an `autogenerated` category (its pages come from the directory
 *   the config names, not from this config file) or an item shape this
 *   parser doesn't recognize.
 */

function walkItems(items, sidebarId, depth, entries, notes) {
  for (const item of items) {
    if (typeof item === "string") {
      entries.push({ kind: "doc", docId: item, depth, sidebarId });
      continue;
    }

    if (item && typeof item === "object" && typeof item.type === "string") {
      switch (item.type) {
        case "doc":
          entries.push({ kind: "doc", docId: item.id, label: item.label, depth, sidebarId });
          break;
        case "category":
          entries.push({ kind: "category", label: item.label, depth, sidebarId });
          if (Array.isArray(item.items)) {
            walkItems(item.items, sidebarId, depth + 1, entries, notes);
          } else if (item.link && item.link.type === "generated-index") {
            notes.push(`Category "${item.label}" has no static items list (generated-index link).`);
          }
          break;
        case "link":
          entries.push({ kind: "link", label: item.label, href: item.href, depth, sidebarId });
          break;
        case "autogenerated":
          entries.push({ kind: "autogenerated", dirName: item.dirName, depth, sidebarId });
          notes.push(
            `Category at depth ${depth} is "autogenerated" from directory "${item.dirName}" -- its pages come from that directory's contents, not this config.`
          );
          break;
        default:
          entries.push({ kind: "unknown", depth, sidebarId });
          notes.push(`Unrecognized sidebar item type "${item.type}" at depth ${depth} -- skipped.`);
      }
      continue;
    }

    notes.push(`Unrecognized sidebar item shape at depth ${depth} -- skipped.`);
    entries.push({ kind: "unknown", depth, sidebarId });
  }
}

export function parseDocusaurusSidebars(parsedJson) {
  const entries = [];
  const notes = [];

  if (!parsedJson || typeof parsedJson !== "object" || Array.isArray(parsedJson)) {
    return { entries, notes: ["sidebars.json's top level is not an object of sidebar IDs."] };
  }

  for (const [sidebarId, items] of Object.entries(parsedJson)) {
    if (!Array.isArray(items)) {
      notes.push(`Sidebar "${sidebarId}" is not an array -- skipped.`);
      continue;
    }
    walkItems(items, sidebarId, 0, entries, notes);
  }

  return { entries, notes };
}
